import { expect } from 'vitest'
import { Projection } from '../../src/typescript/class.js'
import type { Gossip, Sequence } from '../../src/typescript/types/type.js'
/** Test-side alias for a live Projection; no separate replica implementation is involved. */
export type Replica<T> = Projection<T>
/** Distinct fixture Actor IDs; authoring Session identity is generated by the runtime. */
let actor = 10000
/** Creates a shared positive origin for independently forked editing histories. */
export function create_seed<T>(values: Array<T>): Projection<T> {
  const sequence = new Projection<T>(actor++)
  sequence.insert(values, 0)
  return sequence
}
/**
 * Replays one operation set, optionally hydrating and redelivering its received prefix.
 * @param base Trusted starting Sequence shared by the authors.
 * @param mutations Gossip batches in the selected delivery order.
 * @param restartAt Restart after this many batches; Acknowledgements are not fanned back to authors.
 * @returns Receiver after delivery, including any unresolved native dependencies.
 */
export function deliver<T>(
  base: Sequence<T>,
  mutations: Array<Gossip<T>>,
  restartAt?: number
): Projection<T> {
  let sequence = new Projection<T>(actor++, base)
  for (let index = 0; index < mutations.length; ++index) {
    sequence.apply(mutations[index])
    if (index + 1 === restartAt) {
      // Redeliver the received prefix to exercise identity-based deduplication after hydration.
      sequence = new Projection<T>(actor++, sequence.sequence())
      for (let replay = 0; replay <= index; ++replay)
        sequence.apply(mutations[replay])
    }
  }
  return sequence
}
/** Compares visible length and Footage; local gates, jumps and fragmentation may differ. */
export function expect_converged<T>(
  expected: Projection<T>,
  actual: Projection<T>
): void {
  expect(actual.length()).toBe(expected.length())
  expect(actual.values()).toEqual(expected.values())
}
/** Permutes whole Gossip batches reproducibly, retaining each batch's internal entry order. */
export function shuffle_mutations<T>(
  mutations: Array<Gossip<T>>,
  seed: number
): Array<Gossip<T>> {
  const shuffled = [...mutations]
  for (let index = shuffled.length - 1; index > 0; --index) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0
    const other = seed % (index + 1)
    ;[shuffled[index], shuffled[other]] = [shuffled[other], shuffled[index]]
  }
  return shuffled
}
